-- Poker Tournament Survivorship dataset

DROP TABLE IF EXISTS players;

CREATE TABLE players (
    player_id TEXT,
    skill REAL,
    bankroll_mgmt REAL,
    tilt_control REAL,
    study_hours_week REAL,
    tournaments_played INTEGER,
    avg_field_size INTEGER,
    avg_buyin REAL,
    bankroll_buyins INTEGER,
    itm_rate REAL,
    final_table_rate REAL,
    win_rate REAL,
    biggest_cash_x REAL,
    final_bankroll_bi REAL,
    realized_roi REAL,
    went_broke INTEGER,
    profitable INTEGER
);

BEGIN TRANSACTION;
COMMIT;
